import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.ResultSet;
import java.sql.Statement;

// Insert the fixed SMS master code config row for local/e2e 联调 (portal.applogin.sms.master.code=123456).
public class SetMasterCode {
    static String URL = "jdbc:dm://dameng.v2.fangchanzonghe.shiqu.suzhou.dev.zhi.com:5236?SCHEMA=ZHISHU_PORTAL";

    public static void main(String[] args) throws Exception {
        String code = args.length > 0 ? args[0] : "123456";
        try (Connection c = DriverManager.getConnection(URL, "SYSDBA", "DaMeng_qZXhjHBFdEB8kInP");
             Statement s = c.createStatement()) {
            ResultSet rs = s.executeQuery("SELECT COUNT(1) FROM ZHISHU_PORTAL.T_PORTAL_CONFIG WHERE CONFIG_KEY='portal.applogin.sms.master.code'");
            rs.next();
            int exists = rs.getInt(1);
            rs.close();
            if (exists > 0) {
                s.executeUpdate("UPDATE ZHISHU_PORTAL.T_PORTAL_CONFIG SET CONFIG_VALUE='" + code + "', UPDATE_TIME=SYSDATE WHERE CONFIG_KEY='portal.applogin.sms.master.code'");
                System.out.println("UPDATED master code = " + code);
            } else {
                ResultSet idrs = s.executeQuery("SELECT NVL(MAX(CONFIG_ID),0)+1 FROM ZHISHU_PORTAL.T_PORTAL_CONFIG");
                idrs.next();
                long id = idrs.getLong(1);
                idrs.close();
                s.executeUpdate("INSERT INTO ZHISHU_PORTAL.T_PORTAL_CONFIG (CONFIG_ID, CONFIG_NAME, CONFIG_KEY, CONFIG_VALUE, CONFIG_TYPE, CREATE_USER, CREATE_TIME, REMARK) " +
                        "VALUES (" + id + ", 'APP短信万能验证码(联调)', 'portal.applogin.sms.master.code', '" + code + "', 'y', 'system', SYSDATE, " +
                        "'无短信服务环境联调用；配置后/sms直接成功、/login校验该码；生产环境严禁配置，不建行即禁用')");
                System.out.println("INSERTED master code = " + code + " (CONFIG_ID=" + id + ")");
            }
            ResultSet verify = s.executeQuery("SELECT CONFIG_ID, CONFIG_KEY, CONFIG_VALUE FROM ZHISHU_PORTAL.T_PORTAL_CONFIG WHERE CONFIG_KEY='portal.applogin.sms.master.code'");
            verify.next();
            System.out.println("VERIFY: id=" + verify.getLong(1) + " key=" + verify.getString(2) + " value=" + verify.getString(3));
        }
    }
}

