  $login = Invoke-RestMethod -Uri 'http://127.0.0.1:9222/v3.0/portal/appLogin/login' -Method Post -ContentType 'application/json; charset=utf-8' -Body ([System.Text.Encoding]::UTF8.GetBytes($lb)) -TimeoutSec 20
